-- tests/prose_waivers.lua — what the kit's US-English gate MUST NOT correct here.
--
-- Read by `tests/_kit/test_prose.lua` (localization-§5). Per FILE and per WORD, never per file
-- alone: a whole-file waiver hides every OTHER British spelling in a file this repository edits.
-- Every file below is waived for one word and for nothing else, so any other British spelling that
-- lands in it still reddens.

return {
    waived = {
        -- CAPTURED LEGACY DATA. tests/fixtures/legacy/credits.lua is generated by
        -- tools/legacy_capture.lua from the fork at 7ea3dc3 and never hand-edited (its README): its
        -- `readme` field is the fork's README credits paragraph, verbatim, which says "Localisations".
        -- Correcting it would make the fixture stop recording what the fork shipped, which is the
        -- one thing a characterization fixture is for (testing-§13).
        ["tests/fixtures/legacy/credits.lua"] = { localis = true },
        -- A LIBRARY'S FIELD NAME. tests/test_companion.lua's pending() reads `handle.cancelled`, the
        -- field the kit's AceTimer mock (tests/_kit/mock_ace.lua) and AceTimer-3.0 itself set on a
        -- handle CancelTimer has taken back. The code reads their field; it cannot rename it.
        ["tests/test_companion.lua"] = { cancelled = true },
        -- The same field: tests/test_equip_bracket.lua asserts the pending update's AceTimer handle
        -- carries `cancelled` once Suspend has taken it back.
        ["tests/test_equip_bracket.lua"] = { cancelled = true },
        -- The same field: tests/test_em_sync.lua sets it on the rebuild's 10 s AceTimer handle so the
        -- mock, which fires every queued timer at once, holds that cancel off.
        ["tests/test_em_sync.lua"] = { cancelled = true },
        -- The same field: tests/test_dialogs.lua and tests/test_outfit_menu.lua set it on the 10 s
        -- AceTimer handle of an Equipment Manager save waiting on its swap (smoke round 3 E12), for the
        -- same reason.
        ["tests/test_dialogs.lua"] = { cancelled = true },
        ["tests/test_outfit_menu.lua"] = { cancelled = true },
        -- The same field: tests/test_triggers_trade.lua counts the live looping tickers, skipping a
        -- handle the mock AceTimer has marked `cancelled`.
        ["tests/test_triggers_trade.lua"] = { cancelled = true },
        -- The same field: tests/perf_scenes.lua's Scenes.quiet drops the timer-queue entries the
        -- mock AceTimer has marked `cancelled` (on the entry or its handle) after each perf step.
        ["tests/perf_scenes.lua"] = { cancelled = true },
        -- A TRANSLATION. locales/frFR.lua is the French overlay tools/rekey-locales.lua writes from the
        -- legacy OutfitterStrings_fr.lua (design §4.6: test_prose runs over tracked prose,
        -- translations exempt). "utilisé" and "utiliser" are French, not a British -ise spelling.
        ["locales/frFR.lua"] = { utilis = true },
    },
}
